'use strict';
let map=null,mapFilter='all',mapLayer=null,mapMarkers=new Map(),mapBounds=[],mapSource=null,mapRequest=0,mapSelected=null,mapPending=null;
const mapContexts=new Map();let leafletPromise=null;
function saveMapContext(){if(!map)return mapContexts.get(String(mapFilter))||null;const c={center:[map.getCenter().lat,map.getCenter().lng],zoom:map.getZoom(),selected:mapSelected};mapContexts.set(String(mapFilter),c);return c;}
function selectPendingMap(key,step){mapPending={key,step};if(map)selectMapPlace(key,true,step);}
function loadLeaflet(){if(window.L)return Promise.resolve();if(!leafletPromise)leafletPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='assets/leaflet.js';script.onload=resolve;script.onerror=()=>{leafletPromise=null;reject(Error('地图模块尚未缓存或网络不可用'));};document.head.append(script);});return leafletPromise;}
function disposeMap(){mapRequest++;saveMapContext();if(map){map.stop();map.remove();map=null;}mapLayer=null;mapMarkers.clear();}
function updateMapControls(){const cur=$('[data-map-mode=current]'),next=$('[data-map-mode=next]');if(cur)cur.dataset.mapday=String(mapBaseDay);if(next){next.dataset.mapday=String(Math.min(18,mapBaseDay+1));next.disabled=mapBaseDay===18;}$$('[data-mapday]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapday===mapFilter||(b.dataset.mapMode==='day'&&mapFilter!=='all'))));const control=$('[data-map-dates]');if(control)control.textContent=mapFilter==='all'?'选择当日':dateText(DATA.days[+mapFilter-1].date)+' ⌄';moveSlider($('.map-mode'));
 const dayMode=$('[data-map-mode=day]');if(dayMode)dayMode.dataset.mapday=mapFilter==='all'?String(state.day):mapFilter;const select=$('[data-journey-date=map]');if(select&&mapFilter!=='all')select.value=mapFilter;const intro=$('#mapIntro');if(intro)intro.textContent=mapFilter==='all'?'全程地点与自驾道路':'当天主要地点与自驾道路';}
let roadsPromise=null,mapBaseDay=journeyToday();
function loadRoads(){if(typeof ROAD_ROUTES!=='undefined')return Promise.resolve();if(!roadsPromise)roadsPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='assets/road-routes.js';script.onload=resolve;script.onerror=()=>{roadsPromise=null;reject(Error('道路线路暂无法打开'));};document.head.append(script);});return roadsPromise;}
function roadFor(d){return typeof ROAD_ROUTES==='undefined'?null:ROAD_ROUTES[d.id+':'+(state.variants[d.id]||'A')];}
function mapPage(){if(mapFilter!=='all')mapBaseDay=+mapFilter;const today=mapBaseDay;return `<header class="utility-header"><p class="editor-label">ROUTE ATLAS</p><h1>路线地图</h1><div class="segments map-mode" role="group" aria-label="地图日期"><button data-map-mode="current" data-mapday="${today}" aria-pressed="${mapFilter===String(today)}">当天</button><button data-map-mode="next" data-mapday="${Math.min(18,today+1)}" aria-pressed="${mapFilter===String(today+1)}" ${today===18?'disabled':''}>次日</button><button data-mapday="all" aria-pressed="${mapFilter==='all'}">全程</button></div><div class="utility-actions map-date-actions">${journeyDate(mapFilter==='all'?today:+mapFilter,true)}<button data-fit>适应路线</button><button data-map-return>${mapSource?.view==='day'?'返回当日行程':'返回行程'}</button></div><p id="mapIntro">${mapFilter==='all'?'全程地点与自驾道路':'当天主要地点与自驾道路'}</p></header><div class="map-wrap"><div id="routeMap" class="map" aria-label="互动旅程地图"><p class="map-loading">正在打开地图…</p></div></div><p class="info-caption">自驾线沿预存道路绘制；点击导航打开Google Maps。航班和步行不画成自驾路线。路况与通行班次请看当天公告。</p><div id="selectedMapPlace" class="map-selection" aria-live="polite"></div><div id="mapRouteActions"></div><div id="mapPlaces" class="map-place-list"></div>`;}
async function initMap(){const token=++mapRequest;try{await loadLeaflet();try{await loadRoads();}catch{}if(token!==mapRequest||state.view!=='map'||!$('#routeMap'))return;if(map){map.remove();map=null;}$('#routeMap').textContent='';map=L.map('routeMap',{scrollWheelZoom:false,attributionControl:true,zoomAnimation:false,fadeAnimation:!reduced(),markerZoomAnimation:!reduced()});L.geoJSON(GEO,{style:{color:'#a7bcc4',weight:.7,fillColor:'#e6edeb',fillOpacity:1}}).addTo(map);map.attributionControl.addAttribution('Natural Earth · 道路：<a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> / <a href="https://project-osrm.org/">OSRM</a>');mapLayer=L.layerGroup().addTo(map);updateMap();map.on('moveend',()=>saveMapContext());requestAnimationFrame(()=>map?.invalidateSize());}catch(e){if(token!==mapRequest)return;$('#routeMap').innerHTML='<p class="map-loading">互动地图暂不可用，仍可查询下方地点与导航列表。</p>';renderMapList();}}
function mapItems(){if(mapFilter==='all'){const items=[];for(const d of DATA.days)for(const key of selectedRoute(d)){const p=DATA.places[key];if(p&&p.lon<40&&!items.some(x=>x.key===key))items.push({key,p,day:d.id,steps:[]});}return items;}const d=DATA.days[+mapFilter-1],visits=selectedVisits(d),route=selectedRoute(d),items=[];const first=route[0],last=route.at(-1);if(DATA.places[first])items.push({key:first,p:DATA.places[first],day:d.id,steps:[],kind:'起点'});for(const v of visits){let item=items.find(x=>x.key===v.key);if(!item){item={...v,steps:[]};items.push(item);}if(v.step!==null&&!item.steps.some(x=>x.step===v.step))item.steps.push({step:v.step,time:v.time,title:v.title});if(v.kind==='集合 / 报到'||v.kind==='停车地点')item.kind=v.kind;}for(const item of items){if(item.key===last)item.kind=(item.key===first?'起点 / 终点':item.kind?item.kind+' · 终点':'终点');}return items;}
function mapNavLink(item){return item.key.startsWith('hotel:')?hotelLink(item.key.slice(6)):navLink(item.p);}
function placeKind(key){if(key.startsWith('hotel:'))return '住宿地址（原资料未提供坐标）';if(DATA.bookings.some(b=>b.parking===key)||/停车|Parking/.test(DATA.places[key]?.name||''))return '停车地点';if(DATA.bookings.some(b=>(b.meeting||b.spot)===key))return '活动集合 / 报到';return '行程地点';}
function overviewStages(){let html='',current='';for(const d of DATA.days){const phase=phaseOf(d);if(current!==phase){if(current)html+='</section>';current=phase;html+=`<section class="map-stage"><h2>${phase}</h2>`;}html+=`<button class="map-stage-day" data-mapday="${d.id}"><strong>${shortDate(d.date)}</strong><span>${esc(d.title)}</span></button>${(d.flights||[]).map(f=>`<p class="map-transfer">${esc(f[0])} · ${esc(f[2])} ${esc(f[3])} → ${esc(f[5])} ${esc(f[6])}</p>`).join('')}`;}return html+'</section>';}
function drivingKeys(day){const road=roadFor(day);if(road)return road.keys;if(![5,6,7,8,10,11,12,13,14,15].includes(day.id))return [];let keys=selectedRoute(day).filter(k=>DATA.places[k]);const flight=day.flights?.[0];if(flight){const airport=keys.find(k=>k.endsWith('-airport')&&k.split('-')[0].toUpperCase()===(day.id===8?flight[1]:flight[4])),i=keys.indexOf(airport);if(i<0)return [];keys=day.id===8?keys.slice(0,i+1):keys.slice(i);}return keys;}
function routeNavigation(day){const keys=drivingKeys(day);if(!keys.length)return `<p class="info-caption map-mode-note">请按原时间线选择公共交通或逐点导航。${day.drive?esc(day.drive):''}</p>`;if(keys.length<2)return '';const point=k=>{const p=DATA.places[k];return p.lat+','+p.lon;},limited=keys.slice(0,5);let url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(point(limited[0]))+'&destination='+encodeURIComponent(point(limited.at(-1)))+'&travelmode=driving';if(limited.length>2)url+='&waypoints='+encodeURIComponent(limited.slice(1,-1).map(point).join('|'));return `<div class="inline-actions">${ext(url,keys.length>5?'前段自驾地点导航':day.flights?.length?(day.id===8?'飞行前的自驾段导航':'抵达后的自驾段导航'):'按原自驾点位导航','primary-link')}</div><p class="info-caption">只传递原自驾段坐标，外部地图计算真实道路；${day.flights?.length?'航班不计入驾车路线，其他交通见当天时间线。':''}${keys.length>5?'移动端途经点有限，后段请逐个地点导航。':''}道路开放与车辆可达性需现场核对。</p>`;}
function renderMapList(){const items=mapItems();if(mapFilter==='all'){$('#mapPlaces').innerHTML=overviewStages();$('#mapRouteActions').innerHTML='<p class="info-caption">全程已保存道路线；机场区域坐标与道路终点可能有偏差，查看对应日的道路说明。</p>';return;}const d=DATA.days[+mapFilter-1];$('#mapRouteActions').innerHTML=`<h2 class="map-day-title">${dateText(d.date)} · ${esc(d.title)}</h2>${routeNavigation(d)}${roadFor(d)?`<details class="road-disclosures"><summary>道路线路与导航说明</summary><p>路线来自OpenStreetMap与OSRM，已随路书保存；不提供实时路况。${Math.round(roadFor(d).distance/1000)}公里为道路估算，含停车点间的路线。</p>${roadFor(d).diagnostics.map(x=>'<p>'+esc(typeof x==='string'?x:x.message||x.note||JSON.stringify(x))+'</p>').join('')}<p>机场、停车区坐标可能落在区域中心，驶入与停车以现场标志为准。隧道放行班次、收费和临时封路看当日公告。</p></details>`:'<p class="info-caption">此日没有预存自驾线，地点与外部导航仍可使用。</p>'}`;$('#mapPlaces').innerHTML=items.map((x,i)=>`<article class="map-place-row" data-map-row="${x.key}"><button data-map-place="${x.key}"><span class="map-order">${i+1}</span><span><strong>${esc(x.p.name)}</strong><small>${esc(x.kind||placeKind(x.key))}</small></span><span>↗</span></button><div class="map-step-links">${x.steps.length?x.steps.map(s=>`<button data-day="${x.day}" data-focus-step="${s.step}">${esc(s.time)} · ${esc(s.title)} →</button>`).join(''):'<small>原路线点位，未单列时间</small>'}</div><div class="map-row-actions">${ext(mapNavLink(x),'导航到此处','small-link')}${journeyParking(x.key)}<button data-navigation="${x.key}">其他导航方式</button></div></article>`).join('')||'<p>此日仅机场抵达，详见当日安排。</p>';}
function updateMap(){renderMapList();updateMapControls();if(!map||!mapLayer)return;const remembered=mapContexts.get(String(mapFilter));mapLayer.clearLayers();mapMarkers.clear();mapBounds=[];const days=mapFilter==='all'?DATA.days.filter(d=>d.id<18):[DATA.days[+mapFilter-1]];for(const d of days){const road=roadFor(d);if(road)L.geoJSON(road.geometry,{style:{color:'#416e7b',weight:3,opacity:.85}}).addTo(mapLayer);}mapItems().forEach((x,i)=>{if(!Number.isFinite(x.p.lat)||!Number.isFinite(x.p.lon))return;mapBounds.push([x.p.lat,x.p.lon]);const marker=L.marker([x.p.lat,x.p.lon],{title:x.p.name,alt:x.p.name,icon:L.divIcon({className:'map-pin',html:String(i+1),iconSize:[30,30],iconAnchor:[15,15]})}).addTo(mapLayer);marker.on('click',()=>selectMapPlace(x.key,false));mapMarkers.set(x.key,marker);});$('#selectedMapPlace').innerHTML='';mapSelected=null;if(remembered)map.setView(remembered.center,remembered.zoom,{animate:false});else fitMap();if(mapPending){const pending=mapPending;mapPending=null;selectMapPlace(pending.key,true,pending.step);}else if(remembered?.selected)selectMapPlace(remembered.selected,false);}
function fitMap(){if(map&&mapBounds.length)map.fitBounds(mapBounds,{padding:[35,35],maxZoom:12,animate:!reduced()});}
function selectMapVisit(id){selectMapPlace(id);}
function selectMapPlace(key,pan=true,step){const item=mapItems().find(x=>x.key===key);if(!item)return;mapSelected=key;$$('[data-map-row]').forEach(el=>el.classList.toggle('selected',el.dataset.mapRow===key));mapMarkers.forEach((marker,k)=>marker.getElement()?.classList.toggle('selected',k===key));if(pan&&map&&Number.isFinite(item.p.lat)&&Number.isFinite(item.p.lon))map.setView([item.p.lat,item.p.lon],Math.max(map.getZoom(),11),{animate:!reduced()});const target=step??item.steps[0]?.step;$('#selectedMapPlace').innerHTML=`<p class="editor-label">${esc(item.kind||placeKind(key))}</p><h2>${esc(item.p.name)}</h2><p>${esc(item.p.address||item.p.en)}</p><div class="inline-actions">${ext(mapNavLink(item),'导航到此处','primary-link')}${journeyParking(key)}<button data-navigation="${key}">Apple / 其他方式</button><button data-day="${item.day}" ${target!==undefined?`data-focus-step="${target}"`:''}>${target!==undefined?'查看对应安排':'当天安排'} →</button></div>`;saveMapContext();if(pan===false)$('#selectedMapPlace').scrollIntoView({block:'nearest',behavior:reduced()?'instant':'smooth'});}
function navigationBody(key){const p=key.startsWith('hotel:')?DATA.hotels[key.slice(6)]:DATA.places[key];if(!p)return '<p>原路书未提供此地点。</p>';const query=p.address?(p.name+' '+p.address):p.mapQuery||p.en||p.name,dest=Number.isFinite(p.lat)&&Number.isFinite(p.lon)?p.lat+','+p.lon:query;return `<p>${esc(p.name)}<br>${esc(p.address||p.en||'')}</p><div class="navigation-options">${ext(key.startsWith('hotel:')?hotelLink(key.slice(6)):navLink(p),'Google Maps','primary-link')}${ext('https://maps.apple.com/?q='+encodeURIComponent(query)+'&daddr='+encodeURIComponent(dest),'Apple Maps','primary-link')}<button data-copy="${esc(query)}">复制名称与地址</button></div>`;}
